    "dificuldade": 1,
    "conteudo": {
      "objetivos": [
        "Analise “A biblioteca abriu. Os alunos vão ler e a professora organizará os livros”. Separe os períodos, identifique os núcleos verbais e marque as orações. Compare com o aviso “Boa leitura!” e explique por que ele comunica algo mesmo sem verbo."
      ],
      "resumo": "Frase, oração e período",
      "blocos": [
        {
          "tipo": "html",
          "html": "<h2>Frase, oração e período</h2><p>Uma frase produz sentido em uma situação comunicativa e pode não ter verbo: “Silêncio!” funciona como aviso. Uma oração se organiza em torno de um núcleo verbal. Um período pode reunir uma ou mais orações. Na escrita, os limites costumam ser marcados por ponto final, de interrogação ou de exclamação, mas contar sinais sem analisar a construção não basta. Neste estudo trabalharemos exemplos de limites claros, relacionando o que o texto comunica à sua organização.</p><h3>Exemplo comentado</h3><p>No relato “A turma entrou na sala. Todos começaram a ler”, há dois períodos, cada um com uma oração: entrou e começaram a ler são os núcleos verbais. Começaram a ler é tratado aqui como locução verbal: as formas atuam juntas no mesmo processo. Em “A turma entrou e escolheu os livros”, o período reúne duas orações: entrou e escolheu. A segunda retoma o sujeito da primeira. Em “Boa leitura!”, o aviso pode ser uma frase sem oração.</p><h3>Produza e revise</h3><p>Analise “A biblioteca abriu. Os alunos vão ler e a professora organizará os livros”. Separe os períodos, identifique os núcleos verbais e marque as orações. Compare com o aviso “Boa leitura!” e explique por que ele comunica algo mesmo sem verbo.</p>"
        }
      ]
    },
