          "tipo": "html",
          "html": "<h2>Sinônimos: diferenças de sentido</h2><p>Sinônimos têm sentidos próximos em certos contextos, mas sua troca pode alterar intensidade, registro e associações. Dizer, afirmar, sussurrar e gritar podem introduzir um ato de fala. Sussurrar destaca voz baixa; gritar, voz alta; afirmar destaca uma declaração assumida com convicção. Não são equivalentes em todas as cenas. O dicionário oferece possibilidades; o contexto permite avaliar se uma substituição preserva o efeito pretendido.</p><h3>Exemplo comentado</h3><p>“Lia disse o endereço” não informa o volume da voz. “Lia sussurrou o endereço” acrescenta voz baixa. “Lia gritou o endereço” modifica a cena. Ao comparar contente, alegre e eufórica após uma boa notícia, eufórica tende a sugerir entusiasmo mais intenso.</p><h3>Produza e revise</h3><p>Compare “A criança estava contente”, “A criança estava alegre” e “A criança estava eufórica” após uma notícia. Explique o que a última escolha acrescenta. Escreva uma cena com disse e substitua por sussurrou ou gritou, justificando o efeito.</p>"
